/**
 * Watch collection + configurator options. Each watch is either the scanned
 * reference chronograph GLB or a parametric watch generated by the watch
 * engine (src/features/watch). Adding a watch = one entry here.
 */
export type CaseMetal = 'steel' | 'yellow' | 'rose' | 'platinum' | 'titanium' | 'dlc';
export type DialFinish = 'sunray' | 'matte' | 'enamel' | 'skeleton';
export type DialLayout = 'three-hand' | 'day-date' | 'small-seconds' | 'chrono';
export type BezelStyle = 'smooth' | 'fluted' | 'diver' | 'tachymeter' | 'diamond';
export type HandStyle = 'baton' | 'dauphine' | 'sword' | 'leaf' | 'mercedes';
export type MarkerStyle = 'baton' | 'roman' | 'arabic' | 'diamond' | 'dots' | 'minimal';
export type StrapType = 'bracelet' | 'jubilee' | 'leather' | 'rubber' | 'mesh' | 'nato';

export interface WatchSpec {
  caseMetal: CaseMetal;
  dialColor: string;
  dialFinish: DialFinish;
  bezel: BezelStyle;
  bezelColor: string;
  hands: HandStyle;
  markers: MarkerStyle;
  strap: StrapType;
  strapColor: string;
  lume: string;
  accent: string;
  /** two-tone bracelet centre links in gold */
  twoTone: boolean;
  date: boolean;
  exhibitionBack: boolean;
}

export interface WatchGeometry {
  /** case diameter, mm */
  diameter: number;
  thickness: number;
  lugWidth: number;
  layout: DialLayout;
  crownGuards?: boolean;
}

export type OptionGroup = keyof WatchSpec;

export interface WatchProduct {
  id: string;
  name: string;
  collection: string;
  style: string;
  price: number;
  description: string;
  highlights: string[];
  /** 'chronograph-glb' = reference model (public/watches/chronograph.glb) */
  source: { kind: 'glb'; url: string } | { kind: 'parametric'; geometry: WatchGeometry };
  defaults: WatchSpec;
  /** option groups this model supports (the GLB has a fixed hand/marker design) */
  options: OptionGroup[];
  specs: [string, string][];
}

