export const findWatch = (id: string) => WATCHES.find((w) => w.id === id) ?? WATCHES[0];

export function watchPrice(w: WatchProduct, s: WatchSpec) {
  const metal = METALS.find((m) => m.id === s.caseMetal)?.price ?? 0;
  const strap = STRAPS.find((m) => m.id === s.strap)?.price ?? 0;
  const bezel = s.bezel === 'diamond' ? 260000 : 0;
  const markers = s.markers === 'diamond' && w.defaults.markers !== 'diamond' ? 85000 : 0;
  const base = w.defaults.caseMetal === s.caseMetal ? 0 : metal - (METALS.find((m) => m.id === w.defaults.caseMetal)?.price ?? 0);
  return Math.max(60000, w.price + base + strap + bezel + markers);
}
